class Solution:

	def solve(self, root, low, high):
		if root is None:
			return
		if low <= root.data <= high:
			self.cnt += 1
		self.solve(root.left, low, high)
		self.solve(root.right, low, high)

	def getCount(self, root, low, high):
		self.cnt = 0
		self.solve(root, low, high)
		return self.cnt
